class CircularQueue {
    int arr[MAX];
    int front = 0, rear = -1, count = 0;
public:
    bool isEmpty() { return count == 0; }
    bool isFull()  { return count == MAX; }
    int  size()    { return count; }

    void enqueue(int x) {
        if (isFull()) throw overflow_error("Queue Overflow");
        rear = (rear + 1) % MAX;
        arr[rear] = x;
        count++;
    }

    int dequeue() {
        if (isEmpty()) throw underflow_error("Queue Underflow");
        int x = arr[front];
        front = (front + 1) % MAX;
        count--;
        return x;
    }

    int peek() {
        if (isEmpty()) throw underflow_error("Queue is empty");
        return arr[front];
    }

    void display() {
        if (isEmpty()) { cout << "Queue is empty" << endl; return; }
        cout << "Front -> ";
        for (int i = 0; i < count; i++)
            cout << arr[(front + i) % MAX] << " ";
        cout << "<- Rear" << endl;
    }
};

