#include <iostream>
#include <queue>
#include <string>
using namespace std;

struct Patient {
    int token;
    string name;
};

int main() {
    queue<Patient> q;
    int nextToken = 1, choice;
    do {
        cout << "\n1. New patient  2. Call next  3. Waiting count  0. Exit\nChoice: ";
        cin >> choice;
        if (choice == 1) {
            Patient p;
            p.token = nextToken++;
            cout << "Name: "; cin >> p.name;
            q.push(p);
            cout << "Token " << p.token << " given to " << p.name << endl;
        } else if (choice == 2) {
            if (q.empty()) cout << "No patient waiting" << endl;
            else {
                cout << "Calling token " << q.front().token
                     << " (" << q.front().name << ")" << endl;
                q.pop();
            }
        } else if (choice == 3) {
            cout << q.size() << " patient(s) waiting" << endl;
        }
    } while (choice != 0);
    return 0;
}

