bool isPalindrome(const string& s) {
    deque<char> dq;
    for (char c : s) if (isalpha(c)) dq.push_back(tolower(c));
    while (dq.size() > 1) {
        if (dq.front() != dq.back()) return false;
        dq.pop_front();
        dq.pop_back();
    }
    return true;
}
// isPalindrome("Nitin") -> true
