#include <iostream>
#include <queue>
#include <string>
using namespace std;

struct Process { string name; int remaining; };

int main() {
    queue<Process> ready;
    ready.push({"P1", 5});
    ready.push({"P2", 3});
    ready.push({"P3", 1});
    int quantum = 2, time = 0;

    while (!ready.empty()) {
        Process p = ready.front(); ready.pop();
        int run = min(quantum, p.remaining);
        cout << p.name << " runs from " << time << " to " << time + run;
        time += run;
        p.remaining -= run;
        if (p.remaining > 0) { ready.push(p); cout << endl; }
        else cout << "  -> finished" << endl;
    }
    return 0;
}

